// Column chart: one bar per X value, height = Y.
// Size and margins
const margin = { top: 16, right: 16, bottom: 32, left: 48 };

// Y scale: values -> pixels (the left margin fits the longest Y label)
const y = d3.scaleLinear()
    .domain([0, d3.max(data, Y) || 1])
    .nice()
    .range([H - margin.bottom, margin.top]);
margin.left = 14 + 7 * d3.max(y.ticks(5).map(y.tickFormat(5)), s => s.length);

// X scale
const x = d3.scaleBand()
    .domain(data.map(X))
    .range([margin.left, W - margin.right])
    .padding(0.2);

// The chart
const svg = d3.create('svg')
    .attr('viewBox', [0, 0, W, H]);

// Grid lines (Settings)
const grid = g => g
    .call(g => g.select('.domain').remove())
    .selectAll('line')
    .attr('stroke', theme.border)
    .attr('stroke-dasharray', '2,3');

if (opts.grid?.y) {
  svg.append('g')
      .attr('transform', 'translate(' + margin.left + ',0)')
      .call(d3.axisLeft(y)
          .ticks(5)
          .tickSize(-(W - margin.left - margin.right))
          .tickFormat(''))
      .call(grid);
}
if (opts.grid?.x) {
  svg.append('g')
      .attr('transform', 'translate(0,' + (H - margin.bottom) + ')')
      .call(d3.axisBottom(x)
          .tickSize(-(H - margin.top - margin.bottom))
          .tickFormat(''))
      .call(grid);
}

// Axes
svg.append('g')
    .attr('transform', 'translate(0,' + (H - margin.bottom) + ')')
    .call(d3.axisBottom(x).tickSizeOuter(0));

svg.append('g')
    .attr('transform', 'translate(' + margin.left + ',0)')
    .call(d3.axisLeft(y).ticks(5))
    .call(g => g.select('.domain').remove());

// Bars
svg.append('g')
    .attr('fill', colors[0])
  .selectAll('rect')
  .data(data)
  .join('rect')
    .attr('x', d => x(X(d)))
    .attr('y', d => y(Y(d)))
    .attr('width', x.bandwidth())
    .attr('height', d => y(0) - y(Y(d)));

// Value labels (Settings)
if (opts.labels) {
  svg.append('g')
      .attr('fill', theme.text2)
      .attr('font-size', 11)
      .attr('text-anchor', 'middle')
    .selectAll('text')
    .data(data)
    .join('text')
      .attr('x', d => x(X(d)) + x.bandwidth() / 2)
      .attr('y', d => y(Y(d)) - 4)
      .text(d => d3.format('~s')(Y(d)));
}

return svg.node();
